/**
 * THE QA SECTION'S ART SLOTS. The pixel art is generated by the owner (docs/qa-art-prompts.md) and
 * dropped into dashboard/public/qa/. Until a file exists, its slot draws a Night Glass stand-in —
 * a gradient and a line icon — so the section looks finished either way.
 *
 * Like the World view and the bridge decks, this is a deliberate exception to Night Glass's
 * "no sprites" rule: the section has its own drawn art, and everything around it stays Night Glass.
 *
 * QA_ART is the one list of slots: the prompt doc and any future build script iterate it.
 */
import { useState } from 'react';

export const QA_ART = {
  hero: { file: 'hero.png', w: 1600, h: 400, alt: 'QA lab' },
  'module-runner': { file: 'module-runner.png', w: 512, h: 512, alt: 'Runner' },
  'module-explorer': { file: 'module-explorer.png', w: 512, h: 512, alt: 'Explorer' },
  'module-recorder': { file: 'module-recorder.png', w: 512, h: 512, alt: 'Recorder' },
  'empty-tests': { file: 'empty-tests.png', w: 512, h: 512, alt: 'No tests yet' },
  'empty-findings': { file: 'empty-findings.png', w: 512, h: 512, alt: 'No findings yet' },
  'empty-repairs': { file: 'empty-repairs.png', w: 512, h: 512, alt: 'Nothing to review' },
  'empty-journeys': { file: 'empty-journeys.png', w: 512, h: 512, alt: 'No journeys recorded' },
} as const;

export type QaArtName = keyof typeof QA_ART;
export const QA_ART_NAMES = Object.keys(QA_ART) as QaArtName[];
export const qaArtSrc = (name: QaArtName) => `/qa/${QA_ART[name].file}`;

/** The stand-in's line icon, per slot. */
function FallbackIcon({ name }: { name: QaArtName }) {
  const common = { fill: 'none', stroke: 'currentColor', strokeWidth: 1.6, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  if (name === 'module-explorer' || name === 'empty-findings') {
    return <svg viewBox="0 0 24 24" className="w-1/3 h-1/3 max-w-[96px]" {...common}><circle cx="11" cy="11" r="6" /><path d="M20 20l-4.5-4.5M11 8v6M8 11h6" /></svg>;
  }
  if (name === 'module-recorder' || name === 'empty-journeys') {
    return <svg viewBox="0 0 24 24" className="w-1/3 h-1/3 max-w-[96px]" {...common}><circle cx="12" cy="12" r="8" /><circle cx="12" cy="12" r="3" /><path d="M4 4l2 2M20 4l-2 2" /></svg>;
  }
  if (name === 'empty-repairs') {
    return <svg viewBox="0 0 24 24" className="w-1/3 h-1/3 max-w-[96px]" {...common}><path d="M14.5 5.5a4 4 0 0 0-5 5L4 16l4 4 5.5-5.5a4 4 0 0 0 5-5L16 12l-4-4z" /></svg>;
  }
  // hero, runner, tests: a checklist.
  return <svg viewBox="0 0 24 24" className="w-1/3 h-1/3 max-w-[96px]" {...common}><path d="M9 6h11M9 12h11M9 18h11" /><path d="M4 6l1 1 2-2M4 12l1 1 2-2M4 18l1 1 2-2" /></svg>;
}

/**
 * One art slot. Shows the drawn image; if it is missing (or fails to load) shows the stand-in.
 * `className` sizes the slot; the image keeps its own aspect ratio inside it.
 */
export function QaArt({ name, className = '' }: { name: QaArtName; className?: string }) {
  const [missing, setMissing] = useState(false);
  const art = QA_ART[name];
  return (
    <div
      data-qa-art={name}
      data-qa-art-fallback={missing || undefined}
      className={`relative overflow-hidden rounded-[18px] border border-white/[0.08] ${className}`}
      style={{ aspectRatio: `${art.w} / ${art.h}` }}
    >
      {missing ? (
        <div
          role="img"
          aria-label={art.alt}
          className="absolute inset-0 flex items-center justify-center text-neon-200/80 bg-[radial-gradient(ellipse_at_30%_20%,rgba(90,174,255,0.28),transparent_60%),radial-gradient(ellipse_at_80%_90%,rgba(46,230,214,0.16),transparent_55%)] bg-gl-surface"
        >
          <FallbackIcon name={name} />
        </div>
      ) : (
        <img
          src={qaArtSrc(name)}
          alt={art.alt}
          draggable={false}
          onError={() => setMissing(true)}
          className="absolute inset-0 w-full h-full object-cover [image-rendering:pixelated]"
        />
      )}
    </div>
  );
}
